# ============================================================
# Heterogeneity analysis
# ============================================================
#
# Purpose:
#   Assess heterogeneity among genetic instruments using
#   Cochran's Q statistic.
#
# Input:
#   Harmonized MR datasets generated by 02_Univariable_MR.
#
# Output:
#   results/sensitivity/heterogeneity_results.csv
#
# Important:
#   - The same harmonized MR datasets used for the primary
#     random-effects IVW analyses are used here.
#   - No independent SNP selection is performed.
#   - No LD clumping is performed.
#   - No independent harmonisation is performed.
#   - Heterogeneity is treated as a diagnostic assessment and
#     does not trigger automatic SNP exclusion.
#
# Software:
#   R >= 4.5.0
#   TwoSampleMR 0.6.29
#
# ============================================================


# ------------------------------------------------------------
# 1. Packages
# ------------------------------------------------------------

required_packages <- c(
  "here",
  "TwoSampleMR",
  "readr",
  "dplyr"
)

missing_packages <- required_packages[
  !vapply(required_packages, requireNamespace, logical(1), quietly = TRUE)
]

if (length(missing_packages) > 0) {
  stop(
    "The following required packages are not installed: ",
    paste(missing_packages, collapse = ", "),
    call. = FALSE
  )
}

library(here)
library(TwoSampleMR)
library(readr)
library(dplyr)


# ------------------------------------------------------------
# 2. Project directories
# ------------------------------------------------------------

harmonized_dir <- here::here(
  "results",
  "primary_MR",
  "harmonized"
)

output_dir <- here::here(
  "results",
  "sensitivity"
)

dir.create(
  output_dir,
  recursive = TRUE,
  showWarnings = FALSE
)


# ------------------------------------------------------------
# 3. Input files
# ------------------------------------------------------------
#
# These files must correspond exactly to the harmonized
# datasets used by the primary MR analyses.
#
# Replace the entries below with the final filenames generated
# by 02_Univariable_MR.
# ------------------------------------------------------------

harmonized_files <- c(
  # "CRP_on_VaD_overall.csv",
  # "CRP_on_VaD_undefined.csv",
  # "CRP_on_VaD_subcortical.csv",
  # "CRP_on_VaD_multi_infarct.csv",
  # "CRP_on_VaD_mixed.csv"
)

if (length(harmonized_files) == 0) {
  stop(
    paste0(
      "No harmonized MR input files have been specified.\n",
      "Please populate 'harmonized_files' with the exact output ",
      "files generated by 02_Univariable_MR."
    ),
    call. = FALSE
  )
}

harmonized_paths <- file.path(
  harmonized_dir,
  harmonized_files
)

missing_files <- harmonized_paths[
  !file.exists(harmonized_paths)
]

if (length(missing_files) > 0) {
  stop(
    "The following harmonized MR input files do not exist:\n",
    paste(missing_files, collapse = "\n"),
    call. = FALSE
  )
}


# ------------------------------------------------------------
# 4. Validate harmonized MR dataset
# ------------------------------------------------------------

validate_harmonized_data <- function(dat, file_name) {
  
  required_columns <- c(
    "SNP",
    "beta.exposure",
    "se.exposure",
    "beta.outcome",
    "se.outcome",
    "mr_keep"
  )
  
  missing_columns <- setdiff(
    required_columns,
    names(dat)
  )
  
  if (length(missing_columns) > 0) {
    stop(
      paste0(
        "Input file '", file_name,
        "' is missing required columns: ",
        paste(missing_columns, collapse = ", ")
      ),
      call. = FALSE
    )
  }
  
  dat <- dat %>%
    filter(
      !is.na(SNP),
      !is.na(beta.exposure),
      !is.na(se.exposure),
      !is.na(beta.outcome),
      !is.na(se.outcome),
      mr_keep == TRUE
    )
  
  if (nrow(dat) < 2) {
    return(NULL)
  }
  
  dat
}


# ------------------------------------------------------------
# 5. Run heterogeneity analysis
# ------------------------------------------------------------

heterogeneity_results <- list()

for (i in seq_along(harmonized_paths)) {
  
  input_file <- harmonized_paths[i]
  input_name <- basename(input_file)
  
  message(
    "Processing heterogeneity analysis: ",
    input_name
  )
  
  dat <- readr::read_csv(
    input_file,
    show_col_types = FALSE
  )
  
  dat <- validate_harmonized_data(
    dat = dat,
    file_name = input_name
  )
  
  if (is.null(dat)) {
    message(
      "  Fewer than 2 valid SNPs. Heterogeneity analysis skipped."
    )
    next
  }
  
  message(
    "  Valid SNPs: ",
    nrow(dat)
  )
  
  result <- tryCatch(
    {
      TwoSampleMR::mr_heterogeneity(dat)
    },
    error = function(e) {
      warning(
        "Heterogeneity analysis failed for ",
        input_name,
        ": ",
        conditionMessage(e),
        call. = FALSE
      )
      NULL
    }
  )
  
  if (is.null(result) || nrow(result) == 0) {
    next
  }
  
  result <- result %>%
    mutate(
      input_file = input_name,
      .before = 1
    )
  
  heterogeneity_results[[length(heterogeneity_results) + 1]] <-
    result
}


# ------------------------------------------------------------
# 6. Combine results
# ------------------------------------------------------------

heterogeneity_results <- if (
  length(heterogeneity_results) > 0
) {
  bind_rows(heterogeneity_results)
} else {
  tibble()
}


# ------------------------------------------------------------
# 7. Save results
# ------------------------------------------------------------

output_file <- file.path(
  output_dir,
  "heterogeneity_results.csv"
)

readr::write_csv(
  heterogeneity_results,
  output_file,
  na = ""
)

message(
  "\nHeterogeneity analysis completed."
)

message(
  "Results saved to: ",
  output_file
)